#P nonstd 
1/38=1/1; 
2/17=6,18=5,40=1/2; 
3/11=9,16=1,25=1,30=1/1,2,3; 
4//1; 
5/5=2,32=1,38=5/2; 
6/7=2,8=2,9=2,10=2,28=1/1; 
99/5=1,9=1/99;

